function mean(arr) {
  return arr.reduce((sum, x) => sum + x, 0) / arr.length;
}

function pearsonCorrelation(xs, ys) {
  const mx = mean(xs);
  const my = mean(ys);
  let numerator = 0;
  let sumSqX = 0;
  let sumSqY = 0;
  for (let i = 0; i < xs.length; i++) {
    const dx = xs[i] - mx;
    const dy = ys[i] - my;
    numerator += dx * dy;
    sumSqX += dx * dx;
    sumSqY += dy * dy;
  }
  return numerator / Math.sqrt(sumSqX * sumSqY);
}

